    /**
     * Merge Contacts.
     *
     * Manually merge one or more contacts into the contact at {contact_id}.
     *
     * By default the OLDEST contact in the set ({contact_id} plus the secondary_ids) is used as
     * primary. Pass primary_override: true to force {contact_id} as primary even if a secondary is
     * older.
     *
     * All conversations, messages, notes, custom field values, tags, subscriptions, and contact
     * methods are migrated to the primary. The secondary contact rows are hard-deleted; their UUIDs
     * continue to resolve to the primary via contact_aliases.
     *
     * Scopes: contacts:update.
     *
     * @param  list<string>  $secondaryIds  UUIDs of contacts to merge into the primary contact (the {id} in the URL).
     * @param  ?bool  $primaryOverride  When False (default), the oldest contact among {id, *secondary_ids} is used as primary regardless of which UUID is in the URL. Set True to force {id} as primary even if a secondary is older.
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Contacts/merge_contacts_api_v1_contacts__contact_id__merge_post
     */
    public function merge(
        string $contactId,
        array $secondaryIds,
        ?bool $primaryOverride = null,
        ?string $idempotencyKey = null,
    ): MergeContacts {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/contacts/'.Payload::segment($contactId).'/merge',
            body: Payload::body(['secondary_ids' => $secondaryIds, 'primary_override' => $primaryOverride]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return MergeContacts::fromArray($response->data());
    }

    /**
     * Preview Merge Contacts.
     *
     * Preview what merging contacts would do to running flows. Nothing is changed.
     *
     * Takes the same body as POST /contacts/{contact_id}/merge and picks the surviving contact the
     * same way (oldest unless primary_override: true).
     *
     * Running flows of merged contacts keep running on the surviving contact. A flow run is only
     * stopped when the surviving contact is already running the same flow, or when several merged
     * contacts run the same flow (the most recently started one keeps running). The response lists how
     * many runs would be stopped per flow.
