     */
    public function updateMethod(
        string $contactId,
        string $methodId,
        ?string $methodType = null,
        ?string $value = null,
        ?string $displayName = null,
        ?string $phoneType = null,
        ?bool $isPrimary = null,
    ): ContactMethod {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/contacts/'.Payload::segment($contactId).'/methods/'.Payload::segment($methodId),
            body: Payload::body([
                'method_type' => $methodType,
                'value' => $value,
                'display_name' => $displayName,
                'phone_type' => $phoneType,
                'is_primary' => $isPrimary,
            ]),
        ));

        return ContactMethod::fromArray($response->data());
    }

    /**
     * Unblock Contact.
     *
     * Unblock a contact across all channels.
     *
     * Removes the contact block and also removes the email sender blacklist entry if the contact has
     * an email address.
     *
     * Scopes: contacts:update.
     *
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Contacts/unblock_contact_api_v1_contacts__contact_id__unblock_post
     */
    public function unblock(string $contactId, ?string $idempotencyKey = null): void
    {
        $this->connector->send(new Request(
            Method::Post,
            '/contacts/'.Payload::segment($contactId).'/unblock',
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * List Conversation Contact Merge Suggestions.
     *
     * List pending contact merge suggestions for a conversation's contact.
     *
     * A suggestion is created when a live chat visitor enters an email address or phone number (or the
     * website passes a contact ID) that matches an existing contact. The conversation is never linked
     * to that contact automatically: confirm the suggestion to merge the visitor into the existing
     * contact, or dismiss it to keep them separate.
     *
     * matched_value is what the visitor entered and is not verified.
     *
     * Scopes: conversations:read.
     *
     * @param  ?int  $page  Page number (1-indexed)
     * @param  ?int  $pageSize  Items per page
     * @return Page<ContactMergeSuggestion>
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/Contacts/list_conversation_contact_merge_suggestions_api_v1_conversations__conversation_id__contact_merge_suggestions_get
     */
    public function listConversationMergeSuggestions(
        string $conversationId,
        ?int $page = null,
        ?int $pageSize = null,
    ): Page {
        $response = $this->connector->send(new Request(
            Method::Get,
            '/conversations/'.Payload::segment($conversationId).'/contact-merge-suggestions',
            query: Payload::query(['page' => $page, 'page_size' => $pageSize]),
        ));

        return Hydrate::page($response->data(), ContactMergeSuggestion::fromArray(...), fn (int $page): Page => $this->listConversationMergeSuggestions(conversationId: $conversationId, page: $page, pageSize: $pageSize));
    }
}
